namespace axenox\PackageManager\Tests\PHPUnit\Unit;

use axenox\PackageManager\Common\Audit\Scanner\AbstractAuditScanner;
use axenox\PackageManager\Common\Audit\Scanner\ComposerNpmAuditScanner;
use axenox\PackageManager\Common\Audit\Scanner\OsvAuditScanner;
use axenox\PackageManager\Common\Audit\Scanner\NpmOutdatedScanner;
use axenox\PackageManager\Common\Audit\Scanner\PackagistOutdatedScanner;
use axenox\PackageManager\Tests\PHPUnit\Support\AuditTestCase;

/**
 * Checks production HTTP trust options without making network requests.
 */
class AuditHttpTrustTest extends AuditTestCase
{
    /**
     * All registry/advisory clients retain verification and use the shared trust policy.
     *
     * @return void
     */
    public function testProductionClientsKeepVerificationAndShareTrustOptions(): void
    {
        $native = PHP_OS_FAMILY === 'Windows' && extension_loaded('curl') && defined('CURLSSLOPT_NATIVE_CA')
            && ! ini_get('curl.cainfo') && ! ini_get('openssl.cafile') && ! ini_get('openssl.capath')
            && ! getenv('SSL_CERT_FILE') && ! getenv('SSL_CERT_DIR');
        foreach ([ComposerNpmAuditScanner::class, OsvAuditScanner::class, NpmOutdatedScanner::class, PackagistOutdatedScanner::class] as $class) {
            $scanner = new $class($this->workbench);
            $client = (new \ReflectionMethod($class, 'createHttpClient'))->invoke($scanner);
            self::assertTrue($client->getConfig('verify'));
            if ($native) {
                self::assertSame(CURLSSLOPT_NATIVE_CA, $client->getConfig('curl')[CURLOPT_SSL_OPTIONS] & CURLSSLOPT_NATIVE_CA);
            } else {
                self::assertNull($client->getConfig('curl'));
            }
        }
    }

    /**
     * Explicit trust options and unrelated HTTP options must not be overwritten.
     *
     * @return void
     */
    public function testExplicitCaOptionsArePreserved(): void
    {
        $scanner = new ComposerNpmAuditScanner($this->workbench);
        $options = ['verify' => 'operator-ca.pem', 'timeout' => 17, 'headers' => ['User-Agent' => 'fixture']];
        self::assertSame($options, (new \ReflectionMethod(AbstractAuditScanner::class, 'getHttpClientOptions'))->invoke($scanner, $options));
    }
}
